# Initially generated by GitHub Copilot.
from __future__ import annotations

from pathlib import Path
import shutil
import subprocess
from typing import Sequence

from repo_util import maintenance_policy
from repo_util.common import format_command, run_cmd, write_json, write_text
from repo_util.repo_selection import RepoInfo


def _select_black_command(
    repo_dir: Path, target: str, extra_args: Sequence[str]
) -> list[str] | None:
    black_exe = repo_dir / ".venv" / "Scripts" / "black.exe"
    venv_python = repo_dir / ".venv" / "Scripts" / "python.exe"
    tail = [*extra_args, target]

    if black_exe.is_file():
        return [str(black_exe), *tail]
    if venv_python.is_file():
        return [str(venv_python), "-m", "black", *tail]
    path_black = shutil.which("black")
    if path_black is not None:
        return [path_black, *tail]
    return None


def _has_tracked_py_files(repo_dir: Path) -> bool:
    """Whether the repo has any tracked .py file.

    Decides both whether black is RUN at all and whether an unrunnable black is a
    legitimate skip or a problem. Several repos here are data or output repos with
    no Python at all, and for those there is nothing to format; a repo with Python
    and no black is a repo the sweep is quietly passing by.

    ASKED BEFORE BLACK IS EVEN LOOKED FOR, which is not where it started. Until
    2026-08-02 the sweep consulted this only after failing to find a black to run,
    so a Python-less repo that still had a ``.venv`` lying around got the full
    ``black .`` treatment over whatever untracked Python happened to be on disk.
    That is not hypothetical: wlc-utils, emptied of Python on 2026-08-01, kept its
    venv and three orphaned agent worktrees, and the sweep reformatted the 789
    pre-evacuation ``.py`` files inside those worktrees -- files tracked in no
    repo's index. Nothing changed that day because they were already black-clean,
    but the next black version bump would have rewritten every one of them, in a
    checkout nobody was going to commit. ``git ls-files`` is the right question
    precisely because it ignores what is merely lying in the directory.
    """
    result = run_cmd(["git", "-C", str(repo_dir), "ls-files", "*.py"])
    if result.returncode != 0:
        raise RuntimeError(
            result.stderr.strip() or f"Failed to list tracked .py files in {repo_dir}"
        )
    return any(line.strip() for line in result.stdout.splitlines())


def _to_lines(stdout: str | None, stderr: str | None) -> list[str]:
    merged = ""
    if stdout:
        merged += stdout
    if stderr:
        merged += stderr
    return [line for line in merged.splitlines()]


def _render_txt_report(results: list[dict]) -> str:
    lines: list[str] = []
    for item in results:
        black = item["black"]
        lines.append(f"=== {item['repo']} ===")
        lines.append(f"repo_path: {item['repo_path']}")
        lines.append(f"today_commit: {item['today_commit']}")
        if black["attempted"]:
            lines.append(
                "black: "
                f"attempted={black['attempted']} "
                f"success={black['success']} "
                f"exit_code={black['exit_code']}"
            )
            lines.append(f"black_command: {black['command']}")
            for output_line in black["output"]:
                lines.append(f"black_out: {output_line}")
        else:
            lines.append(
                "black: " f"attempted={black['attempted']} " f"note={black['note']}"
            )
        if black["problem"]:
            lines.append(f"black_problem: {black['problem']}")
        lines.append("")
    return "\n".join(lines) + "\n"


def problem_repos(results: list[dict]) -> list[str]:
    """Names of repos the sweep failed to format, in report order."""
    return [item["repo"] for item in results if item["black"]["problem"]]


def run_black_across_repos(
    repo_infos: list[RepoInfo],
    *,
    black_target: str,
    black_timeout_sec: float | None,
    frozen_repos: dict[str, dict],
    vendored_package_names: list[str],
    vendored_overrides: dict[str, list[str]],
    source_repo: Path,
    report_json: Path | None,
    report_txt: Path | None,
) -> list[dict]:
    results: list[dict] = []

    for repo_info in repo_infos:
        black_result = {
            "attempted": False,
            "success": False,
            "exit_code": None,
            "command": "",
            "output": [],
            "note": "",
            "problem": "",
        }

        # A vendored copy is maintained in its source repo, so leave it as it
        # arrives. MAM-basics is that source, and formats its own originals.
        extra_args: list[str] = []
        if repo_info.path != source_repo:
            extra_args = [
                "--extend-exclude",
                maintenance_policy.vendored_exclude_regex(
                    vendored_package_names,
                    vendored_overrides.get(repo_info.name),
                ),
            ]

        frozen = frozen_repos.get(repo_info.name)
        has_tracked_py = _has_tracked_py_files(repo_info.path)
        command = (
            None
            if frozen is not None or not has_tracked_py
            else _select_black_command(repo_info.path, black_target, extra_args)
        )

        if frozen is not None:
            black_result["note"] = (
                f"Skipped: frozen ({frozen['comment']}"
                f" last commit when frozen {frozen['last_commit_when_frozen']})"
            )
        elif not has_tracked_py:
            black_result["note"] = "Skipped: no tracked .py files in this repo"
        elif command is None:
            black_result["problem"] = (
                "black unavailable, but this repo has tracked .py files: no"
                " .venv/Scripts/black.exe, no .venv/Scripts/python.exe, and no"
                " black on PATH. Create the repo's .venv so the sweep covers it."
            )
        else:
            black_result["attempted"] = True
            black_result["command"] = format_command(command)
            try:
                result = run_cmd(
                    command, cwd=repo_info.path, timeout_sec=black_timeout_sec
                )
                black_result["exit_code"] = result.returncode
                black_result["success"] = result.returncode == 0
                black_result["output"] = _to_lines(result.stdout, result.stderr)
                if not black_result["success"]:
                    black_result["problem"] = f"black exited {result.returncode}"
            except subprocess.TimeoutExpired as exc:
                black_result["success"] = False
                black_result["note"] = (
                    f"Timed out after {black_timeout_sec} seconds while running black"
                )
                black_result["problem"] = (
                    f"black timed out after {black_timeout_sec} seconds"
                )
                stdout = exc.stdout if isinstance(exc.stdout, str) else ""
                stderr = exc.stderr if isinstance(exc.stderr, str) else ""
                black_result["output"] = _to_lines(stdout, stderr)

        results.append(
            {
                "repo": repo_info.name,
                "repo_path": str(repo_info.path),
                "today_commit": repo_info.head_commit,
                "today_commit_source": "head-committer-date",
                "black": black_result,
            }
        )

    if report_json is not None:
        write_json(report_json, results)
    if report_txt is not None:
        write_text(report_txt, _render_txt_report(results))

    print(f"REPO_COUNT={len(results)}")
    for result in results:
        black_result = result["black"]
        line = "REPO={0}; BLACK_ATTEMPTED={1}; BLACK_OK={2}".format(
            result["repo"],
            black_result["attempted"],
            black_result["success"],
        )
        if black_result["problem"]:
            line += f"; PROBLEM={black_result['problem']}"
        elif black_result["note"]:
            line += f"; {black_result['note']}"
        print(line)

    problems = problem_repos(results)
    if problems:
        print(f"BLACK_PROBLEM_COUNT={len(problems)}; REPOS={', '.join(problems)}")

    return results
